options:
set key = $ORDER(y(""))
while key '= "" {
    write y(key)
    set key1 = $ORDER(y(key))
}

set node = $QUERY(y)
while node '= "" {
    write node
    set node = $QUERY(node)
}

set key1 = $ORDER(y(""))
while key1 '= "" {
    set key2 = $ORDER(y(key1, ""))
    while key2 '= "" {
         write y(key1, key2)
         set key2 = $ORDER(y(key1,key2))
    }
    set key1 = $ORDER(y(key1))
}

set node = $QUERY(y(""), 1, target)
while node '= "" {
    set node = $QUERY(node)
}
set node = $QUERY(y(node, ""), 1, target)
while node '= "" {
    write node
    set node = $QUERY(node, "")
}
